package com.citysense.mesh.protocol;

/**
 * Layer 3 — Offline Field Hazard / Observation report.
 * Generated by field responders or citizens during network disruptions.
 */
public record FieldReportPayload(
        String reportType,
        Double latitude,
        Double longitude,
        Integer severity,
        String description,
        String reporterRole) {

    public FieldReportPayload {
        reportType = reportType != null ? reportType : "HAZARD";
        latitude = latitude != null ? latitude : 30.3165;
        longitude = longitude != null ? longitude : 78.0322;
        severity = severity != null ? Math.max(1, Math.min(severity, 5)) : 3;
        description = description != null ? description : "";
        reporterRole = reporterRole != null ? reporterRole : "CITIZEN";
    }
}
